#include <boost/multiprecision/cpp_int.hpp>
#include <cassert>
#include <iostream>
#include <string>
using boost::multiprecision::cpp_int;

static cpp_int pow10(unsigned e) {
  cpp_int r = 1;
  for (unsigned i = 0; i < e; ++i) r *= 10;
  return r;
}

static cpp_int modpow(cpp_int a, cpp_int e, const cpp_int& n) {
  cpp_int r = 1 % n;
  a %= n;
  while (e > 0) {
    if ((e & 1) != 0) r = (r * a) % n;
    a = (a * a) % n;
    e >>= 1;
  }
  return r;
}

struct Case {
  const char* name;
  unsigned A;
  unsigned E;
  unsigned D;
  const char* expected_n;
  const char* expected_residue;
};

int main() {
  const Case cases[] = {
    {"q1_3", 740, 733, 2391,
      "",
      ""},
    {"q2_0", 370, 666, 2177,
      "",
      ""},
  };

  unsigned mutations = 0;
  for (const auto& c : cases) {
    cpp_int numerator = cpp_int(c.A) * pow10(c.E) + 1;
    assert(numerator % c.D == 0);
    cpp_int n = numerator / c.D;
    cpp_int expected_n(c.expected_n);
    cpp_int expected_r(c.expected_residue);
    assert(n == expected_n);
    assert(n > 2 && (n & 1) == 1);
    cpp_int r = modpow(2, n - 1, n);
    assert(r == expected_r);
    assert(r != 1);

    assert(n + 1 != expected_n);
    ++mutations;
    assert((r + 1) % n != expected_r);
    ++mutations;

    std::cout << c.name << " digits=" << c.E
              << " fermat_failure=1\n";
  }
  std::cout << "CPP_EXACT_FERMAT_PASS cases=2 mutations="
            << mutations << "\n";
  return 0;
}
